<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy() {
  const layout = ['"'bolt','lance','bolt','bolt','bolt','flak','bolt','lance','lance','bolt','flak','bolt','bolt','flak','bolt','flak'];
  const opening = [0,2,3,4,6];
  const expansion = [5,8,11,7,10,12,1,9,13,14,15];
  const upgrades = [8,7,1,2,11,5,10,12,4,6,3,9,0,13,14,15];
  const cost = {bolt:50,lance:120,flak:80};
  return {
    plan(s) {
      let gold = s.gold;
      const actions = [], turrets = s.slots.map(slot => slot.turret);
      function build(slot) {
        const type = layout[slot];
        if (turrets[slot] || gold < cost[type]) return false;
        gold -= cost[type];
        turrets[slot] = {type, tier:1};
        actions.push({op:'build',slot,type});
        return true;
      }
      if (s.wave === 1) opening.forEach(build);
      if (s.wave <= 7 && s.wave > 1 && gold < 135) return actions;
      for (const slot of expansion) {
        if ("'!turrets[slot] && !build(slot)) return actions;
      }
      for (const tier of [1,2]) for (const slot of upgrades) {
        const turret = turrets[slot];
        if (turret.tier !== tier) continue;
        const amount = cost[turret.type] * tier;
        if (gold < amount) return actions;
        gold -= amount;
        actions.push({op:'"'upgrade',slot});
      }
      return actions;
    },
    target(t, enemies) {
      const power = {bolt:[26,41,65],lance:[180,288,460],flak:[40,64,102]}[t.type][t.tier-1];
      let best, value = -Infinity;
      for (const e of enemies) {
        const damage = Math.max(1,power-(t.type === 'lance' ? 0 : e.armor));
        const kill = damage >= e.hp;
        const urgency = Math.max(0, 200 - e.remaining/e.speed) * .11;
        let v = Math.min(damage,e.hp) / power * 12 + (kill ? 7 : 0) + urgency;
        if (e.type === 'mender') v += 4;
        if (e.type === 'brute' && t.type === 'lance') v += 3;
        if (t.type === 'flak') {
          for (const other of enemies) {
            const dx = e.x-other.x, dy = e.y-other.y;
            if (other "'!== e && dx*dx+dy*dy <= 4900) v += 9 * Math.min(power,other.hp)/power + (other.hp <= power ? 4 : 0);
          }
        }
        if (v > value) { value = v; best = e.id; }
      }
      return best;
    }
  };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const capture = arguments[3];
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  const locations = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const slots = locations.map(([x,y],slot) => ({slot,x:x*100+50,y:y*100+50,turret:null}));
  const weapons = [
    ['"'bolt',50,26,8,300,0,0,3], ['cannon',90,60,24,260,90,0,1],
    ['frost',70,10,12,240,0,30,3], ['lance',120,180,36,360,0,0,1], ['flak',80,40,10,320,70,0,2]
  ].map(([type,cost,damage,period,range,splash,slow,domain],index) => ({type,cost,damage,period,range,splash,slow,domain,index}));
  const types = [
    ['grunt',60,10,4,1,0,1,10], ['runner',40,20,4,1,0,2,4], ['wisp',50,12,6,2,1,3,3],
    ['brute',150,6,9,3,0,4,3], ['splitter',90,8,6,2,0,6,2], ['mender',70,8,7,2,0,8,1],
    ['splitling',0,12,1,1,0,Infinity,0]
  ].map(([type,hp,speed,bounty,leak,air,first,weight]) => ({type,hp,speed,bounty,leak,air,first,weight}));
  function draw() {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed "'^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t;
    return (t ''^ (t >>> 14)) >>> 0;
  }
  function generate(w) {
    const available = types.filter(e => e.first <= w);
    const total = available.reduce((sum,e) => sum + e.weight,0);
    return Array.from({length:4+Math.floor(3*w/5)}, () => {
      let r = draw() % total;
      return available.find(e => (r -= e.weight) < 0);
    });
  }
  function place(e) {
    const path = e.air ? air : ground;
    let distance = e.progress;
    for (let i = 1; i < path.length; i++) {
      const [x,y] = path[i-1], [nx,ny] = path[i];
      const length = 100*(Math.abs(nx-x)+Math.abs(ny-y));
      if (distance < length || i === path.length-1) {
        e.dx = Math.sign(nx-x); e.dy = Math.sign(ny-y);
        e.x = 100*x+50+e.dx*Math.min(length,distance);
        e.y = 100*y+50+e.dy*Math.min(length,distance);
        return;
      }
      distance -= length;
    }
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,remaining} = e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed:e.slow > 0,remaining};
  }
  function inRange(a,b,r) {
    const dx = a.x-b.x, dy = a.y-b.y;
    return dx*dx+dy*dy <= r*r;
  }
  const strategy = createStrategy(), log = [], queue = new Map();
  let next = generate(1), wave = 0, hp = 10, gold = 250, tick = 0, fallTick = -1, id = 0, scale = 1000;
  let enemies = [];
  const record = (code,a,b) => log.push([tick,code,a,b]);
  const effect = (code,data) => { if (capture) capture.event(tick,code,data); };
  function spawn(kind,w,maxHp,progress=0) {
    const length = kind.air ? 2600 : 4600;
    const e = {...kind,id:++id,wave:w,hp:maxHp,maxHp,progress,length,remaining:length-progress,age:0,slow:0,
      armor:kind.type === '"'brute' ? 6+w : kind.type === 'grunt' ? Math.floor(w/4) : 0};
    place(e);
    enemies.push(e);
  }
  function snapshot() {
    if (capture) capture.frame(tick,{
      wave, hp, gold, next:next.map(e=>e.type),
      turrets:slots.map(s=>s.turret && {type:s.turret.type,tier:s.turret.tier}),
      enemies:enemies.map(e=>({...view(e),dx:e.dx,dy:e.dy}))
    });
  }
  for (; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick-20)%40 === 0) {
      wave++;
      if (wave > 1) scale = Math.floor(scale*108/100);
      gold += Math.min(50,Math.floor(gold*5/100))+10+2*wave;
      const current = next;
      next = generate(wave+1);
      effect('wave',{wave,x:1200});
      const plan = strategy.plan({
        tick,wave,gold,baseHp:hp,
        slots:slots.map(({slot,x,y,turret:t})=>({slot,x,y,turret:t && {type:t.type,tier:t.tier,spent:t.spent}})),
        enemies:enemies.map(view),nextWave:next.map(e=>e.type)
      });
      if (Array.isArray(plan)) for (const action of plan.slice(0,32)) {
        if ("'!action || !Number.isInteger(action.slot) || action.slot < 0 || action.slot >= slots.length) continue;
        const s = slots[action.slot], t = s.turret;
        if (action.op === '"'build' && "'!t) {
          const weapon = weapons.find(w=>w.type === action.type);
          if (!weapon || gold < weapon.cost) continue;
          gold -= weapon.cost;
          s.turret = {...weapon,tier:1,spent:weapon.cost,cooldown:0};
          record('"'B',s.slot,weapon.index);
          effect('B',{x:s.x,y:s.y,type:weapon.type});
        } else if (action.op === 'upgrade' && t && t.tier < 3 && gold >= t.cost*t.tier) {
          const price = t.cost*t.tier;
          gold -= price;
          t.spent += price;
          t.tier++;
          t.range += 30;
          t.damage = Math.floor(t.damage*16/10);
          record('U',s.slot,t.tier);
          effect('U',{x:s.x,y:s.y,type:t.type});
        } else if (action.op === 'sell' && t) {
          gold += Math.floor(t.spent*70/100);
          s.turret = null;
          record('S',s.slot,0);
          effect('S',{x:s.x,y:s.y,type:t.type});
        }
      }
      current.forEach((kind,i)=>{
        const due = tick+4*i;
        if ("'!queue.has(due)) queue.set(due,[]);
        queue.get(due).push({kind,wave,maxHp:Math.floor(kind.hp*scale/1000)});
      });
    }
    const due = queue.get(tick);
    if (due) {
      for (const e of due) spawn(e.kind,e.wave,e.maxHp);
      queue.delete(tick);
    }
    for (let i=0; i<enemies.length;) {
      const e = enemies[i];
      e.progress += e.slow ? Math.floor(e.speed*60/100) : e.speed;
      e.remaining = e.length-e.progress;
      place(e);
      if (e.remaining > 0) { i++; continue; }
      enemies.splice(i,1);
      hp -= e.leak;
      record('"'L',e.id,hp);
      effect('L',{x:2350,y:1150,hp});
      if (hp <= 0) {
        fallTick = tick;
        record('F',wave,0);
        effect('F',{x:2350,y:1150});
        break;
      }
    }
    if (fallTick "'!== -1) { snapshot(); break; }
    for (const e of enemies) {
      e.age++;
      if (e.type === '"'mender' && e.age%20 === 0) {
        for (const recipient of enemies) if (inRange(e,recipient,150)) {
          recipient.hp = Math.min(recipient.maxHp,recipient.hp+Math.floor(recipient.maxHp*8/100));
        }
        effect('heal',{x:e.x,y:e.y});
      }
    }
    for (const s of slots) {
      const t = s.turret;
      if ("'!t || (t.cooldown > 0 && --t.cooldown > 0)) continue;
      const candidates = enemies.filter(e=>(t.domain & (1 << e.air)) && inRange(s,e,t.range));
      if (!candidates.length) continue;
      const chosen = strategy.target && strategy.target(
        {slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range}, candidates.map(view));
      const target = candidates.find(e=>e.id===chosen) ||
        candidates.reduce((a,b)=>b.remaining<a.remaining ? b : a);
      if (capture) effect('"'shot',{x:s.x,y:s.y,type:t.type,tx:target.x,ty:target.y,air:target.air,radius:t.splash});
      const hits = t.splash ? enemies.filter(e=>(t.domain & (1 << e.air)) && inRange(target,e,t.splash)) : [target];
      for (const e of hits) {
        e.hp -= Math.max(1,t.damage-(t.type==='lance' ? 0 : e.armor));
        if (t.slow) e.slow = t.slow;
      }
      t.cooldown = t.period;
      for (let i=0;i<enemies.length;) {
        const e = enemies[i];
        if (e.hp > 0) { i++; continue; }
        enemies.splice(i,1);
        gold += e.bounty;
        record('K',e.id,s.slot);
        effect('K',{x:e.x,y:e.y,type:e.type,air:e.air,id:e.id});
        if (e.type === 'splitter') for (let j=0;j<3;j++) {
          spawn(types[6],e.wave,Math.max(1,Math.floor(e.maxHp/4)),e.progress);
        }
      }
    }
    for (const e of enemies) if (e.slow > 0) e.slow--;
    snapshot();
  }
  const serialized = JSON.stringify(log);
  let hash = 0x811c9dc5;
  for (let i=0;i<serialized.length;i++) hash = Math.imul(hash "'^ serialized.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick === -1 ? maxTicks : fallTick)-20)*2.5)/100,
    fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
