const a = rampartSimulate(() => ({plan(s){const a=[];let g=s.gold;for(const sl of s.slots)if("'!sl.turret&&g>=50){a.push({op:'"'build',slot:sl.slot,type:'bolt'});g-=50;}return a;}}),42,12020);
const b = rampartSimulate(() => ({plan(s){return ({1:[{op:'build',slot:3,type:'cannon'},{op:'build',slot:6,type:'frost'}],3:[{op:'upgrade',slot:3},{op:'build',slot:12,type:'flak'}],6:[{op:'build',slot:8,type:'lance'},{op:'sell',slot:6}]})[s.wave]||[];}}),7,12020);
for(const r of [a,b]) print(r.score,r.fallTick,r.log.length,r.hash,JSON.stringify(r.log.slice(0,6)));
for(const s of [42,7,11,21,100,12345]) {const r=rampartSimulate(createStrategy,s,12020);print(s,r.score,r.fallTick,r.hash);}
\"\"\")
